# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_label_shows_snapped_times_and_duration(self):
        labels = round_spans([Span(542, 1033)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_exact_half_rounds_up(self):
        labels = round_spans([Span(15, 75)], 30)
        self.assertEqual(labels, ["00:30-01:30 (1h 0m)"])

    def test_step_of_sixty_snaps_to_whole_hours(self):
        labels = round_spans([Span(541, 1019)], 60)
        self.assertEqual(labels, ["09:00-17:00 (8h 0m)"])

    def test_keeps_one_label_per_span_in_order(self):
        spans = [Span(600, 660), Span(540, 600)]
        self.assertEqual(
            round_spans(spans, 10),
            ["10:00-11:00 (1h 0m)", "09:00-10:00 (1h 0m)"],
        )

    def test_empty_input(self):
        self.assertEqual(round_spans([], 15), [])

    def test_span_that_snaps_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 544)], 15)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 120, 7.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(540, 600)], step)
